<?php if(!defined('ABSPATH')) exit;
function andre_metas(){ add_meta_box('andre_acao','Dados da Ação','andre_acao_box','acoes_projetos'); add_meta_box('andre_emenda','Dados da Emenda','andre_emenda_box','emendas'); add_meta_box('andre_galeria','Imagens da Galeria','andre_galeria_box','galerias'); }
add_action('add_meta_boxes','andre_metas');
function andre_acao_box($p){ wp_nonce_field('andre_meta','andre_nonce'); foreach(['cidade','data','status','link_externo'] as $k){ echo '<p><label>'.esc_html($k).'</label><input style="width:100%" name="'.$k.'" value="'.esc_attr(get_post_meta($p->ID,$k,true)).'"></p>'; }}
function andre_emenda_box($p){ wp_nonce_field('andre_meta','andre_nonce'); foreach(['municipio','valor','ano','beneficiario','objeto','status','orgao_executor','processo','transparencia'] as $k){ echo '<p><label>'.esc_html($k).'</label><input style="width:100%" name="'.$k.'" value="'.esc_attr(get_post_meta($p->ID,$k,true)).'"></p>'; }}
function andre_galeria_box($p){ wp_nonce_field('andre_meta','andre_nonce'); $ids=get_post_meta($p->ID,'galeria_ids',true); echo '<input type="hidden" id="galeria_ids" name="galeria_ids" value="'.esc_attr($ids).'"><button class="button" id="andre_pick_gallery">Selecionar imagens</button><p>IDs: '.esc_html($ids).'</p><p>Use shortcode: [andre_galeria id="'.(int)$p->ID.'"]</p>'; }
add_action('save_post',function($id){ if(!isset($_POST['andre_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['andre_nonce'])),'andre_meta')||!current_user_can('edit_post',$id)) return; $keys=['cidade','data','status','link_externo','municipio','valor','ano','beneficiario','objeto','orgao_executor','processo','transparencia','galeria_ids']; foreach($keys as $k){ if(isset($_POST[$k])) update_post_meta($id,$k, sanitize_text_field(wp_unslash($_POST[$k]))); } });
